"""The old comparison and its replacement use the same recovered m1 and hash calls."""
BASE='ntruplus/proof/768/ref/linear_rrec/'
PROCEDURES=BASE+'NTRUPlus768RRecNativeProcedures.ec'
COMPARISON=BASE+'NTRUPlus768RRecNativeComparison.ec'
PROOF=BASE+'NTRUPlus768RRecNativeProof.ec'
RULES=(
 (PROCEDURES,'native regeneration uses actual CBD then forward NTT serialization and the existing finish kernel',r'module NativeRegenerateFinish = { proc run(recovered:W8.t Array1152.t,hashout:W8.t Array224.t,decode_fail:W32.t) : W8.t Array32.t * W32.t = { var r1,r1ntt:pke_poly; var regenerated:W8.t Array1152.t; var ss:W8.t Array32.t; var status:W32.t; r1 <@ NTRUPlus768PolyCBD1Checked.M.jade_ntruplus_ntruplus768_amd64_ref_poly_cbd1(witness,complete_hash_tail hashout); r1ntt <@ NTRUPlus768NTT.M.jade_ntruplus_ntruplus768_amd64_ref_ntt(witness,r1); regenerated <@ NTRUPlus768PolyToBytes.M.jade_ntruplus_ntruplus768_amd64_ref_poly_tobytes(witness,r1ntt); (ss,status) <@ NTRUPlus768DecapFinish.M.jade_ntruplus_ntruplus768_amd64_ref_decap_finish(witness,hashout,recovered,regenerated,decode_fail); return(ss,status); } }.'),
 (PROCEDURES,'re-encryption uses the same H output tail and received m1 with the original finish status',r'module ReencryptFinish = { proc run(pk ct:W8.t Array1152.t,m1:pke_poly,hashout:W8.t Array224.t,decode_fail:W32.t) : W8.t Array32.t * W32.t = { var r1:pke_poly; var ct2:W8.t Array1152.t option; var ss:W8.t Array32.t; var status:W32.t; r1 <@ NTRUPlus768PolyCBD1Checked.M.jade_ntruplus_ntruplus768_amd64_ref_poly_cbd1(witness,complete_hash_tail hashout); ct2 <@ PKEEnc.run(pk,m1,r1); ss <- encap_zero_ss; status <- W32.one; if(ct2<>None){ (ss,status) <@ NTRUPlus768DecapFinish.M.jade_ntruplus_ntruplus768_amd64_ref_decap_finish(witness,hashout,ct,oget ct2,decode_fail); } return(ss,status); } }.'),
 (PROCEDURES,'replacement tail preserves the actual H input preparation and stateful H call',r'module ReencryptTail(H:CompleteSHAKEH) = { proc run(pk ct:W8.t Array1152.t,m1:pke_poly,msg:W8.t Array96.t,decode_fail:W32.t,suffix:W8.t Array32.t) : W8.t Array32.t * W32.t = { var input:W8.t Array129.t; var hashout:W8.t Array224.t; var result:W8.t Array32.t * W32.t; input <@ NTRUPlus768DecapHashHPrepare.M.jade_ntruplus_ntruplus768_amd64_ref_decap_hash_h_prepare(witness,msg,suffix); hashout <@ H.shake(input); result <@ ReencryptFinish.run(pk,ct,m1,hashout,decode_fail); return result; } }.'),
 (PROCEDURES,'comparison replacement passes the original GuardedR2 message polynomial through the original G path',r'module ReencryptCore(G:MessageSHAKE,H:CompleteSHAKEH) = { proc run(pk ct:W8.t Array1152.t,sk:W8.t Array2336.t) : W8.t Array32.t * W32.t = { var rp,mp:pke_poly; var ss:W8.t Array32.t; var status:W32.t; var bs:W8.t Array1152.t; var msg:W8.t Array96.t; (rp,mp,ss,status) <@ GuardedR2.run(witness,witness,witness,witness,witness,encap_zero_ss,ct,complete_sk_poly sk); if(status=W32.zero){ (bs,msg,status) <@ DecapMessage(G).run(witness,witness,witness,rp,mp); (ss,status) <@ ReencryptTail(H).run(pk,ct,mp,msg,status,complete_sk_suffix sk); } return(ss,status); } }.'),
 (PROCEDURES,'workspace clear remains an unconditional actual kernel call after the core',r'module ReencryptDecaps(G:MessageSHAKE,H:CompleteSHAKEH) = { proc run(pk ct:W8.t Array1152.t,sk:W8.t Array2336.t,workspace:W8.t Array13506.t) : W8.t Array32.t * W32.t * W8.t Array13506.t = { var ss:W8.t Array32.t; var status:W32.t; (ss,status) <@ ReencryptCore(G,H).run(pk,ct,sk); workspace <@ NTRUPlus768DecapClear.M.jade_ntruplus_ntruplus768_amd64_ref_decap_clear(workspace); return(ss,status,workspace); } }.'),
 (COMPARISON,'native byte comparison and encryption use exactly the same decoded message from the stored key',r'lemma rrec_native_compare_reencrypt w ct hout : pke_key_relation w=> complete_entry_accepts ct w.`kg_sk=> ((NTRUPlus768PolyToBytesAlgebra.poly_tobytes_spec(message_r2 ct(complete_sk_poly w.`kg_sk))= complete_regenerated hout)= (pke_enc_spec w.`kg_pk (message_candidate ct(complete_sk_poly w.`kg_sk)) (poly_cbd1_spec(complete_hash_tail hout))=Some ct)).'),
 (PROOF,'generic actual equivalence retains H noninterference, both oracle states, and cleared workspace',r'lemma native_reencrypt_decaps (G<:MessageSHAKE) (H<:CompleteSHAKEH {-G}) w ct0 : pke_key_relation w => equiv[CompleteDecaps(G,H).run ~ ReencryptDecaps(G,H).run: ct{1}=ct0 /\ ct{2}=ct0 /\ sk{1}=w.`kg_sk /\ sk{2}=w.`kg_sk /\ pk{2}=w.`kg_pk /\ ={workspace,glob G,glob H} ==> ={res,glob G,glob H} /\ res.`3{1}=clear_zero_spec].'),
 (PROOF,'concrete distinct ROM maps instantiate the actual equivalence for arbitrary ciphertext bytes',r'lemma native_reencrypt_rom_decaps w ct0 : pke_key_relation w => equiv[CompleteDecaps(SHAKEGROM,SHAKEHROM).run ~ ReencryptDecaps(SHAKEGROM,SHAKEHROM).run: ct{1}=ct0 /\ ct{2}=ct0 /\ sk{1}=w.`kg_sk /\ sk{2}=w.`kg_sk /\ pk{2}=w.`kg_pk /\ ={workspace,ROG.m,ROH.m} ==> ={res,ROG.m,ROH.m} /\ res.`3{1}=clear_zero_spec].'),
)
MUTATIONS=(
 ('native-regeneration-omits-forward-NTT',PROCEDURES,'r1ntt <@ NTRUPlus768NTT.M.jade_ntruplus_ntruplus768_amd64_ref_ntt(witness,r1);','r1ntt <- r1;'),
 ('native-comparison-invents-an-inverse-NTT-trit-guard-on-recovered-r2',PROCEDURES,'if(status=W32.zero){',r'if(status=W32.zero /\ pke_domain(rrec_normalize(invntt_spec rp))){'),
 ('replacement-finish-resamples-coins-instead-of-using-H-output',PROCEDURES,'ct2 <@ PKEEnc.run(pk,m1,r1);','r1 <$ pke_psi1; ct2 <@ PKEEnc.run(pk,m1,r1);'),
 ('replacement-tail-substitutes-a-fixed-H-answer',PROCEDURES,'hashout <@ H.shake(input); result <@ ReencryptFinish.run','hashout <- witness; result <@ ReencryptFinish.run'),
 ('replacement-core-skips-the-actual-G-message-call',PROCEDURES,'(bs,msg,status) <@ DecapMessage(G).run(witness,witness,witness,rp,mp);','(bs,msg,status) <- (witness,witness,W32.zero);'),
 ('replacement-core-reencodes-SOTP-instead-of-retaining-decoded-m1',PROCEDURES,'ReencryptTail(H).run(pk,ct,mp,msg,status,complete_sk_suffix sk)','ReencryptTail(H).run(pk,ct,poly_sotp_encode_spec msg witness,msg,status,complete_sk_suffix sk)'),
 ('replacement-core-forgets-incoming-decode-failure',PROCEDURES,'ReencryptTail(H).run(pk,ct,mp,msg,status,complete_sk_suffix sk)','ReencryptTail(H).run(pk,ct,mp,msg,W32.zero,complete_sk_suffix sk)'),
 ('replacement-decapsulation-skips-actual-workspace-clear',PROCEDURES,'workspace <@ NTRUPlus768DecapClear.M.jade_ntruplus_ntruplus768_amd64_ref_decap_clear(workspace);','workspace <- workspace;'),
 ('native-comparison-uses-a-new-message-in-place-of-decoded-m1',COMPARISON,'pke_enc_spec w.`kg_pk (message_candidate ct(complete_sk_poly w.`kg_sk))','pke_enc_spec w.`kg_pk (poly_sotp_encode_spec witness witness)'),
 ('generic-native-equivalence-removes-H-noninterference-restriction',PROOF,'lemma native_reencrypt_decaps (G<:MessageSHAKE) (H<:CompleteSHAKEH {-G})','lemma native_reencrypt_decaps (G<:MessageSHAKE) (H<:CompleteSHAKEH)'),
 ('generic-native-equivalence-adds-an-oracle-losslessness-premise',PROOF,'lemma native_reencrypt_decaps (G<:MessageSHAKE) (H<:CompleteSHAKEH {-G}) w ct0 :','lemma native_reencrypt_decaps (G<:MessageSHAKE) (H<:CompleteSHAKEH {-G}) w ct0 : islossless H.shake =>'),
 ('concrete-native-equivalence-forgets-ROM-table-state',PROOF,r'={res,ROG.m,ROH.m} /\ res.`3{1}=clear_zero_spec].',r'={res} /\ res.`3{1}=clear_zero_spec].'),
 ('concrete-native-equivalence-omits-malformed-ciphertext-cases',PROOF,'lemma native_reencrypt_rom_decaps w ct0 : pke_key_relation w =>','lemma native_reencrypt_rom_decaps w ct0 : pke_key_relation w => encap_key_canonical ct0 =>'),
)
